// Start
// Handle for one issued xDMA transfer. `task_id` is the value the committed finish
// counter must reach; `remote` records WHICH counter the hardware bumped
// (0 = LOCAL, 1 = REMOTE).
//
// THE ENGINE DECIDES, NOT THE ADDRESS. A transfer whose source is another
// endpoint's memory is run by that peer, and the hardware bumps the REMOTE commit
// counter for it; a purely local move bumps LOCAL. Software cannot tell the two
// apart reliably from the src/dst bits, so guessing means waiting on a counter that
// never advances -- which is an unbounded spin, and therefore presents as a
// simulation that runs for ever rather than as an error. Carrying the bit in the
// handle keeps the provenance per transfer, so it stays correct with several
// transfers in flight.
typedef struct {
    uint32_t task_id;
    uint8_t remote;
} snax_xdma_task_t;

static inline snax_xdma_task_t snax_xdma_start_task() {
    uint32_t local_task_id = snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR);
    uint32_t remote_task_id = snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR);
    snax_write_xdma_cfg_reg(XDMA_START_PTR, 1);
    while (1) {
        uint32_t l = snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR);
        if (l != local_task_id) return (snax_xdma_task_t){l, 0};
        uint32_t r = snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR);
        if (r != remote_task_id) return (snax_xdma_task_t){r, 1};
    }
}

static inline uint32_t snax_xdma_start() {
    uint32_t local_task_id = snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR);
    uint32_t remote_task_id =
        snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR);
    snax_write_xdma_cfg_reg(XDMA_START_PTR, 1);
    while (1) {
        // Wait for xdma to start
        if (snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR) !=
            local_task_id) {
            return snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR);
        }
        if (snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR) !=
            remote_task_id) {
            return snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR);
        }
    }
}

// Whether a task is done, given the finish counter it retires on. The task and finish counters
// are 8 bits (XDMACtrl) and wrap every 256 tasks, so the test is on the difference: done once
// the counter is at the task's id or up to 127 past it. A plain `finished >= id` returns at once
// for the task that wraps -- id 0 against a counter still at 255 -- before it has moved a byte.
static inline int snax_xdma_task_done(uint32_t finished, uint32_t task_id) {
    return ((finished - task_id) & 0xFFu) < 0x80u;
}

// Wait xdma to finished
static inline void snax_xdma_local_wait(uint32_t task_id) {
    while (!snax_xdma_task_done(snax_read_xdma_cfg_reg(XDMA_FINISH_LOCAL_TASK_PTR), task_id)) {
        // Wait for xdma to finish
    }
}

static inline void snax_xdma_remote_wait(uint32_t task_id) {
    while (!snax_xdma_task_done(snax_read_xdma_cfg_reg(XDMA_FINISH_REMOTE_TASK_PTR), task_id)) {
        // Wait for xdma to finish
    }
}

// Wait on the counter the hardware actually used for THIS transfer. Pair with
// snax_xdma_start_task(); `snax_xdma_local_wait(snax_xdma_start())` is only correct
// when the transfer is known to be local.
static inline void snax_xdma_wait_task(snax_xdma_task_t task) {
    if (task.remote) {
        snax_xdma_remote_wait(task.task_id);
    } else {
        snax_xdma_local_wait(task.task_id);
    }
}

static inline uint32_t snax_xdma_last_task_cycle() {
    return snax_read_xdma_cfg_reg(XDMA_PERF_CTR_TASK);
}

static inline uint32_t snax_xdma_last_read_cycle() {
    return snax_read_xdma_cfg_reg(XDMA_PERF_CTR_READER);
}

static inline uint32_t snax_xdma_last_write_cycle() {
    return snax_read_xdma_cfg_reg(XDMA_PERF_CTR_WRITER);
}

// A contiguous main-memory -> L1 read, the second way into the cluster.
//
// The iDMA reads main memory as AXI reads: AR out of the cluster's wide port,
// the data back on R, then into the TCDM through the wide DMA port. The xDMA
// reads it through the endpoint that sits on main memory: the local engine sees
// a source that is not its own and forwards a cfg frame to that endpoint, which
// reads its memory and pushes the bytes back as AXI WRITES (AW/W) into this
// cluster's xDMA data window; the xDMA's writer then stores them through its
// eight 64-bit TCDM ports. The two transfers use opposite directions of the
// wide link and different TCDM paths, so they can run at the same time
// (sw/apps/snax-xdma-idma-read-bw measures how close to twice one port that
// gets).
//
// Every CSR address below is a compile-time constant, and the loops over the
// temporal dimensions unroll: snax_xdma_memcpy_nd() builds its addresses at run
// time, and csrw_ss() with a computed address becomes a jump-table load out of
// main memory plus an indirect jump, about 92 cycles a write; here each write
// is one csrw. Only the xDMA's own hart can write these CSRs.

#define SNAX_XDMA_BEAT 64u

// Arm a read of `beats` 64-byte beats from `src` (main memory) to `dst` (L1),
// both contiguous. The unused multicast destination slots keep their reset
// value of zero.
__attribute__((always_inline)) static inline void snax_xdma_read_arm(
    uint32_t dst, uint32_t src, uint32_t beats) {
    snax_write_xdma_cfg_reg(XDMA_SRC_ADDR_PTR_LSB, src);
    snax_write_xdma_cfg_reg(XDMA_SRC_ADDR_PTR_MSB, 0);
    snax_write_xdma_cfg_reg(XDMA_DST_ADDR_PTR_LSB, dst);
    snax_write_xdma_cfg_reg(XDMA_DST_ADDR_PTR_MSB, 0);
    snax_write_xdma_cfg_reg(XDMA_SRC_SPATIAL_STRIDE_PTR, 8);
    snax_write_xdma_cfg_reg(XDMA_DST_SPATIAL_STRIDE_PTR, 8);
    // One loop of `beats`; every outer loop runs once.
    snax_write_xdma_cfg_reg(XDMA_SRC_TEMP_BOUND_PTR, beats);
    snax_write_xdma_cfg_reg(XDMA_SRC_TEMP_STRIDE_PTR, SNAX_XDMA_BEAT);
#pragma unroll
    for (uint32_t d = 1; d < XDMA_SRC_TEMP_DIM; d++) {
        snax_write_xdma_cfg_reg(XDMA_SRC_TEMP_BOUND_PTR + d, 1);
        snax_write_xdma_cfg_reg(XDMA_SRC_TEMP_STRIDE_PTR + d, 0);
    }
    snax_write_xdma_cfg_reg(XDMA_DST_TEMP_BOUND_PTR, beats);
    snax_write_xdma_cfg_reg(XDMA_DST_TEMP_STRIDE_PTR, SNAX_XDMA_BEAT);
#pragma unroll
    for (uint32_t d = 1; d < XDMA_DST_TEMP_DIM; d++) {
        snax_write_xdma_cfg_reg(XDMA_DST_TEMP_BOUND_PTR + d, 1);
        snax_write_xdma_cfg_reg(XDMA_DST_TEMP_STRIDE_PTR + d, 0);
    }
    // Exactly the engine's eight channels on both sides: a reader told it owns
    // 32 waits on twenty-four that never answer, and the task never retires.
    snax_write_xdma_cfg_reg(XDMA_SRC_ENABLED_CHAN_PTR, 0xFFu);
    snax_write_xdma_cfg_reg(XDMA_DST_ENABLED_CHAN_PTR, 0xFFu);
    snax_write_xdma_cfg_reg(XDMA_DST_ENABLED_BYTE_PTR, 0xFFFFFFFFu);
    // No extension and no junction on the way: whatever an earlier task left
    // armed (a memset's writer extension, a junction) would otherwise act on
    // these bytes.
    snax_write_xdma_cfg_reg(XDMA_SRC_ENABLE_PTR, 0);
    snax_write_xdma_cfg_reg(XDMA_DST_ENABLE_PTR, 0);
    snax_write_xdma_cfg_reg(XDMA_DST_JCT_ENABLE_PTR, 0);
}

// Re-point an armed read. Both base addresses are rewritten, not just the
// destination: the engine consumes its address registers as it walks, so a
// task issued without restoring them reads from wherever the previous one
// ended.
__attribute__((always_inline)) static inline void snax_xdma_read_retask(
    uint32_t dst, uint32_t src, uint32_t beats) {
    snax_write_xdma_cfg_reg(XDMA_SRC_ADDR_PTR_LSB, src);
    snax_write_xdma_cfg_reg(XDMA_SRC_ADDR_PTR_MSB, 0);
    snax_write_xdma_cfg_reg(XDMA_DST_ADDR_PTR_LSB, dst);
    snax_write_xdma_cfg_reg(XDMA_DST_ADDR_PTR_MSB, 0);
    snax_write_xdma_cfg_reg(XDMA_SRC_TEMP_BOUND_PTR, beats);
    snax_write_xdma_cfg_reg(XDMA_DST_TEMP_BOUND_PTR, beats);
}

// Start the armed task, as snax_xdma_start_task() does, but bounded: after
// `limit` polls without a commit, `*timeout` is set and the returned handle's
// id can never be reached.
static inline snax_xdma_task_t snax_xdma_start_bounded(uint32_t limit,
                                                       int* timeout) {
    uint32_t l0 = snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR);
    uint32_t r0 = snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR);
    snax_write_xdma_cfg_reg(XDMA_START_PTR, 1);
    for (uint32_t s = 0; s < limit; s++) {
        uint32_t l = snax_read_xdma_cfg_reg(XDMA_COMMIT_LOCAL_TASK_PTR);
        if (l != l0) return (snax_xdma_task_t){l, 0};
        uint32_t r = snax_read_xdma_cfg_reg(XDMA_COMMIT_REMOTE_TASK_PTR);
        if (r != r0) return (snax_xdma_task_t){r, 1};
    }
    *timeout = 1;
    return (snax_xdma_task_t){0xFFFFFFFFu, 0};
}

// Wait for one issued task on the counter the hardware used for it, as
// snax_xdma_wait_task() does, but bounded: an xDMA that never answers otherwise
// presents as a simulation that never ends. Returns 1 on timeout. One loop per
// counter, so each poll reads a constant CSR address.
static inline int snax_xdma_wait_bounded(snax_xdma_task_t t, uint32_t limit) {
    if (t.remote) {
        for (uint32_t s = 0; s < limit; s++)
            if (snax_xdma_task_done(
                    snax_read_xdma_cfg_reg(XDMA_FINISH_REMOTE_TASK_PTR),
                    t.task_id))
                return 0;
    } else {
        for (uint32_t s = 0; s < limit; s++)
            if (snax_xdma_task_done(
                    snax_read_xdma_cfg_reg(XDMA_FINISH_LOCAL_TASK_PTR),
                    t.task_id))
                return 0;
    }
    return 1;
}
